import{_ as t,a as o,b as a}from"./chunks/mongodb-3.BarKu11r.js";import{_ as s,o as n,c as r,a3 as i}from"./chunks/framework.C6m_RRf-.js";const b=JSON.parse('{"title":"MongoDB Atlas","description":"","frontmatter":{},"headers":[],"relativePath":"en/mongodb-atlas.md","filePath":"en/mongodb-atlas.md","lastUpdated":1789921234000}'),c={name:"en/mongodb-atlas.md"};function l(d,e,g,m,p,u){return n(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="mongodb-atlas" tabindex="-1">MongoDB Atlas <a class="header-anchor" href="#mongodb-atlas" aria-label="Permalink to &quot;MongoDB Atlas&quot;">​</a></h1><p>MongoDB Atlas is the managed MongoDB service provided by MongoDB Inc. A free account gets 500 MiB of storage permanently, which is more than enough for Twikoo comments.</p><ol><li>Register a <a href="https://www.mongodb.com/cloud/atlas/register" target="_blank" rel="noreferrer">MongoDB Atlas</a> account.</li><li>Create a free MongoDB cluster. Pick a region close to your Twikoo backend (Vercel / Netlify / AWS Lambda / VPS) for lower database latency. If you are not sure where your backend runs, <code>AWS / Oregon (us-west-2)</code> is a reasonable default: mature infrastructure, low failure rate and clean energy.</li><li>On the <strong>Database Access</strong> page, click <strong>Add New Database User</strong>, choose <strong>Password</strong> as the authentication method, then set a username and password. Clicking <strong>Auto Generate</strong> gives you a strong password without special characters — save it somewhere safe. Under <strong>Database User Privileges</strong>, click <strong>Add Built In Role</strong>, select <strong>Atlas Admin</strong>, then click <strong>Add User</strong>.</li></ol><p><img src="'+t+'" alt=""></p><ol start="4"><li>On the <strong>Network Access</strong> page, click <strong>Add IP Address</strong> to add a network whitelist entry. Because the egress addresses of Vercel / Netlify / Lambda are not fixed, enter <code>0.0.0.0/0</code> (allow connections from any IP). If Twikoo is deployed on your own server, you can enter a fixed IP instead. Click <strong>Confirm</strong> to save.</li></ol><p><img src="'+o+'" alt=""></p><ol start="5"><li>On the <strong>Database</strong> page, click <strong>Connect</strong>, choose <strong>Drivers</strong>, and note the connection string. Replace <code>&lt;username&gt;:&lt;password&gt;</code> in the string with the database user you just created.</li></ol><p><img src="'+a+'" alt=""></p><ol start="6"><li>(Optional) The default connection string does not specify a database name, so Twikoo connects to the default database named <code>test</code>. If you need to run other services in the same MongoDB instance, or share it between several Twikoo instances, append the database name and configure the corresponding ACL.</li></ol><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>The connection string contains everything needed to access your MongoDB database. If it leaks, anyone can add, modify or delete comments, and may also obtain your SMTP credentials, image-hosting tokens and other secrets. Keep this string safe — you will need to paste it into your Twikoo deployment platform.</p></div>',10)])])}const w=s(c,[["render",l]]);export{b as __pageData,w as default};
